CREATE OR REPLACE VIEW VW_AUDITORIA_DETALHADA ( COD_USUARIO, COD_HOTEL, COD_SETOR, COD_AUDITORIA_EVENTO, NUM_IP, DSC_EVENTO, COD_ENTIDADE, NOM_ENTIDADE, DSC_OPERACAO, NOM_USUARIO, NOM_HOTEL, NOM_SETOR, COD_AUDITORIA_ALTERACAO, NOM_TABELA, COD_REGISTRO, NOM_CAMPO, DSC_VALOR_ANTERIOR, DSC_VALOR_NOVO, DT_EVENTO ) AS
SELECT TB_USUARIO.COD_USUARIO AS COD_USUARIO,
  TB_HOTEL.COD_HOTEL AS COD_HOTEL,
  TB_SETOR.COD_SETOR,
  TB_AUDITORIA_EVENTO.COD_AUDITORIA_EVENTO,
  TB_AUDITORIA_EVENTO.NUM_IP,
  TB_AUDITORIA_EVENTO.DSC_EVENTO,
  TB_AUDITORIA_EVENTO.COD_ENTIDADE,
  TB_AUDITORIA_EVENTO.NOM_ENTIDADE,
  TB_AUDITORIA_EVENTO.DSC_OPERACAO,
  TB_USUARIO.NOM_USUARIO,
  TB_HOTEL.NOM_HOTEL,
  TB_SETOR.NOM_SETOR,
  TB_AUDITORIA_ALTERACAO.COD_AUDITORIA_ALTERACAO,
  TB_AUDITORIA_ALTERACAO.NOM_TABELA,
  TB_AUDITORIA_ALTERACAO.COD_REGISTRO,
  TB_AUDITORIA_ALTERACAO.NOM_CAMPO,
  TB_AUDITORIA_ALTERACAO.DSC_VALOR_ANTERIOR,
  TB_AUDITORIA_ALTERACAO.DSC_VALOR_NOVO,
  TB_AUDITORIA_EVENTO.DT_EVENTO
FROM TB_AUDITORIA_EVENTO
  LEFT JOIN TB_AUDITORIA_ALTERACAO ON TB_AUDITORIA_EVENTO.COD_AUDITORIA_EVENTO =
    TB_AUDITORIA_ALTERACAO.COD_AUDITORIA_EVENTO
  LEFT JOIN TB_USUARIO
    ON TB_USUARIO.COD_USUARIO = TB_AUDITORIA_EVENTO.COD_USUARIO
  LEFT JOIN TB_HOTEL ON TB_HOTEL.COD_HOTEL = TB_AUDITORIA_EVENTO.COD_HOTEL
  LEFT JOIN TB_SETOR ON TB_SETOR.COD_SETOR = TB_AUDITORIA_EVENTO.COD_SETOR 
;

CREATE OR REPLACE VIEW VW_RESUMO_PROTOCOLO_SETOR ( DSC_STATUS, DSC_PRIORIDADE, COD_HOTEL, NOM_HOTEL, COD_SETOR, NOM_SETOR, QTD_PROTOCOLOS, DT_PROTOCOLO_MAIS_ANTIGO, DT_PROTOCOLO_MAIS_RECENTE ) AS
SELECT TB_PROTOCOLO.DSC_STATUS,
  TB_PROTOCOLO.DSC_PRIORIDADE,
  TB_HOTEL.COD_HOTEL,
  TB_HOTEL.NOM_HOTEL,
  TB_SETOR.COD_SETOR,
  TB_SETOR.NOM_SETOR,
  Count(TB_PROTOCOLO.COD_PROTOCOLO) AS QTD_PROTOCOLOS,
  Min(TB_PROTOCOLO.DT_ABERTURA) AS DT_PROTOCOLO_MAIS_ANTIGO,
  Max(TB_PROTOCOLO.DT_ABERTURA) AS DT_PROTOCOLO_MAIS_RECENTE
FROM TB_PROTOCOLO
  INNER JOIN TB_HOTEL ON TB_HOTEL.COD_HOTEL = TB_PROTOCOLO.COD_HOTEL
  INNER JOIN TB_SETOR ON TB_SETOR.COD_SETOR = TB_PROTOCOLO.COD_SETOR_ATUAL
GROUP BY TB_PROTOCOLO.DSC_STATUS,
  TB_PROTOCOLO.DSC_PRIORIDADE,
  TB_HOTEL.COD_HOTEL,
  TB_HOTEL.NOM_HOTEL,
  TB_SETOR.COD_SETOR,
  TB_SETOR.NOM_SETOR 
;

CREATE OR REPLACE VIEW VW_USUARIO_CONSULTA ( COD_USUARIO, NOM_USUARIO, DSC_EMAIL, DSC_SITUACAO, DT_CRIACAO, DT_ULTIMO_LOGIN, DT_ATUALIZACAO ) AS
SELECT TB_USUARIO.COD_USUARIO,
  TB_USUARIO.NOM_USUARIO,
  TB_USUARIO.DSC_EMAIL,
  TB_USUARIO.DSC_SITUACAO,
  TB_USUARIO.DT_CRIACAO,
  TB_USUARIO.DT_ULTIMO_LOGIN,
  TB_USUARIO.DT_ATUALIZACAO
FROM TB_USUARIO 
;

CREATE OR REPLACE TRIGGER HOTEL_GESTAO."Auditoria Alteração_COD_AUDITO" 
BEFORE INSERT ON HOTEL_GESTAO.TB_AUDITORIA_ALTERACAO 
FOR EACH ROW 
WHEN (NEW.COD_AUDITORIA_ALTERACAO IS NULL) 
BEGIN 
    :NEW.COD_AUDITORIA_ALTERACAO := HOTEL_GESTAO.seq_cod_auditoria_alteracao.NEXTVAL; 
END;
/

